#!/bin/bash
# Runs as root while the lab image is built (see Dockerfile). It turns a plain Ubuntu 24.04 box into "web-01":
#   - a user called asha, in the adm group (adm may read the logs in /var/log)
#   - an nginx access log and the API's own log, generated by gen_logs.py (a GENERATED SAMPLE, not real traffic)
#   - the app's settings in /srv/allcsvideos, as deployed by release v2.14.0, plus the previous release for comparison
set -e
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq && apt-get install -y -qq python3 >/dev/null   # python3 only runs gen_logs.py
useradd -m -s /bin/bash -G adm asha

# logs
install -d -m 755 /var/log/nginx /var/log/allcsvideos
mkdir -p /root/gen && cd /root/gen && python3 /root/gen_logs.py .
install -o www-data -g adm -m 640 access.log /var/log/nginx/access.log
install -o www-data -g adm -m 640 /dev/null /var/log/nginx/error.log
install -o root -g adm -m 640 api.log /var/log/allcsvideos/api.log
touch -d '2026-10-19 21:51:59' /var/log/nginx/access.log /var/log/allcsvideos/api.log
touch -d '2026-10-19 20:00:00' /var/log/nginx/error.log
rm -rf /root/gen

# the app's settings, as deployed by release v2.14.0, and the previous release kept for rollback
install -d -o asha -g asha -m 755 /srv/allcsvideos /srv/allcsvideos/releases /srv/allcsvideos/releases/v2.13.4
cat > /srv/allcsvideos/app.env <<'X'
# allcsvideos API settings
# release v2.14.0

APP_ENV=production
WORKERS=2
LOG_LEVEL=info
PAYMENT_URL=https://payments.example.net/v1
PAYMENT_TIMEOUT_MS=300
X
sed 's/v2.14.0/v2.13.4/; s/^PAYMENT_TIMEOUT_MS=300$/PAYMENT_TIMEOUT_MS=3000/' /srv/allcsvideos/app.env > /srv/allcsvideos/releases/v2.13.4/app.env
chown asha:asha /srv/allcsvideos/app.env /srv/allcsvideos/releases/v2.13.4/app.env
chmod 640 /srv/allcsvideos/app.env /srv/allcsvideos/releases/v2.13.4/app.env
touch -d '2026-10-19 21:39:50' /srv/allcsvideos/app.env
touch -d '2026-10-12 18:02:11' /srv/allcsvideos/releases/v2.13.4/app.env
